with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('bopæl', 'word', 'edf03391-a10c-5025-9668-e17e4a3811a4', 1, 'noun', 'en', 'place of residence', 'Hun har fast bopæl i København.', 'She has permanent residence in Copenhagen.'), ('formulering', 'word', 'fa2fc9f5-a8ce-55fd-abf6-b5f82dc86fa6', 1, 'noun', 'en', 'wording, phrasing', 'Kontrakten har en uklar formulering.', 'The contract has an unclear wording.'), ('retfærdighed', 'word', 'a0bb0195-0218-5065-84e0-b1d21bd19b6e', 1, 'noun', 'en', 'justice', 'Han kæmper for retfærdighed.', 'He fights for justice.'), ('trend', 'word', '4523c81a-6e3f-5a4c-9c92-9fbd024f6792', 1, 'noun', 'en', 'trend', 'Det er en ny trend blandt unge.', 'It''s a new trend among young people.'), ('skylle', 'word', 'ed87733f-a9cd-5c12-a884-f67241220b6e', 1, 'verb', null, 'to rinse', 'Husk at skylle håret grundigt.', 'Remember to rinse your hair thoroughly.'), ('symbolsk', 'word', '8f7f8d43-a10e-5fd7-9fe8-e6a72bd41043', 1, 'adjective', null, 'symbolic', 'Gaven havde stor symbolsk værdi.', 'The gift had great symbolic value.'), ('kommissær', 'word', '36fc409e-9c72-5864-bfea-73f76dc4e693', 1, 'noun', 'en', 'commissioner', 'EU-kommissæren holdt en pressekonference.', 'The EU commissioner held a press conference.'), ('prioritering', 'word', '1ece79d8-f586-57a6-bccd-a5ab484a33c3', 1, 'noun', 'en', 'prioritization', 'God prioritering sparer os tid.', 'Good prioritization saves us time.'), ('udbryde', 'word', '371a11df-4c37-52de-90c2-81ef6e910889', 1, 'verb', null, 'to exclaim', 'Hun plejer at udbryde højt, når hun bliver glad.', 'She tends to exclaim loudly when she''s happy.'), ('asyl', 'word', '3ea405b4-aee2-5673-bae2-a2f152aa7658', 1, 'noun', 'et', 'asylum (political)', 'Familien søgte asyl i landet.', 'The family sought asylum in the country.'), ('svin', 'word', 'f12bae4b-41d7-5932-bfd9-d61a49697c6c', 1, 'noun', 'et', 'pig (animal)', 'Bonden opdrætter svin på gården.', 'The farmer raises pigs on