ing (industry)', 'Fiskeri er en vigtig erhverv i byen.', 'Fishing is an important trade in the town.'), ('forudsætte', 'word', 'f2158faf-7980-5e3a-ad1b-16c8d5dedab6', 1, 'verb', null, 'to presuppose, require (as a condition)', 'Jobbet forudsætter gode sprogkundskaber.', 'The job requires good language skills.'), ('døbe', 'word', 'c5c2c9bd-d669-53c8-8595-84d7f86c7f56', 1, 'verb', null, 'to baptize, christen', 'De vil døbe deres søn til sommer.', 'They will baptize their son this summer.'), ('kære', 'word', 'f16a10d5-ba04-5aa5-8ed1-4b63db0a11b0', 1, 'noun', 'en', 'beloved, darling (dear person)', 'Hun skrev et brev til sin kære.', 'She wrote a letter to her beloved.'), ('overtale', 'word', 'df0ecca4-b879-50b2-abe9-5942f6528831', 1, 'verb', null, 'to persuade, talk into', 'Hun overtalte ham til at blive.', 'She persuaded him to stay.'), ('afhandling', 'word', 'd912765c-be16-53de-b12e-5769369da1f5', 1, 'noun', 'en', 'thesis, dissertation', 'Han forsvarede sin afhandling i går.', 'He defended his thesis yesterday.'), ('præsentation', 'word', '8c4a5208-e4ca-5362-9b85-9e9cfc9f6f5e', 1, 'noun', 'en', 'presentation', 'Hun holdt en flot præsentation for kunderne.', 'She gave a great presentation for the clients.'), ('kompetent', 'word', '70e67e04-eccf-56dd-8074-436a7dc5cf7b', 1, 'adjective', null, 'competent', 'Hun er en meget kompetent læge.', 'She is a very competent doctor.'), ('bekostning', 'word', 'b4ec9259-7752-578a-a9bd-ab6829b74151', 1, 'noun', 'en', 'at the expense of', 'Han vandt på bekostning af sin bror.', 'He won at the expense of his brother.'), ('fremfor', 'word', 'a4082961-3981-52cc-adf3-eaebbdf9692d', 1, 'preposition', null, 'rather than, instead of', 'Vælg tog fremfor bil, når du kan.', 'Choose the train rather than the car when you can.'), ('møgso', 'word', 'f8086a9d-4116-5af4-90ab-42374acd7392', 1, 'noun', 'en', 'bitch, cow (insult for a woman)', 'Han kaldte hende et møgso.', 'He called her a bitch.'), ('pynte', 'word', 'd8d6c897-8083-5ddd-ac95-28f9a3c6ff4