1, 'noun', 'et', 'clip (of video), excerpt', 'Vi så et klip fra filmen.', 'We watched a clip from the film.'), ('genial', 'word', 'faa14f1a-3ed3-56d7-902c-08c7b8c9b69b', 1, 'adjective', null, 'brilliant, ingenious', 'Det var en genial idé.', 'It was a brilliant idea.'), ('kunstakademi', 'word', '16a1271f-daba-528e-9eb3-163e08f38139', 1, 'noun', 'et', 'art academy', 'Hun studerer på Kunstakademiet.', 'She studies at the Art Academy.'), ('opdele', 'word', '74ef1054-2937-56b3-a57a-fdbec49fb76b', 1, 'verb', null, 'to divide, split up', 'Vi opdeler klassen i to grupper.', 'We''re splitting the class into two groups.'), ('ballet', 'word', 'fb548283-6721-54d3-9097-1e95f1e26fa5', 1, 'noun', 'en', 'ballet', 'Hun går til ballet hver uge.', 'She goes to ballet every week.'), ('opdrage', 'word', 'bb8e2e86-cc1c-5a96-8490-67201f3fb4aa', 1, 'verb', null, 'to raise, bring up (children)', 'De opdrager deres børn med kærlighed.', 'They raise their children with love.'), ('æstetisk', 'word', '80d254f4-d10b-5741-9d58-0e31f13dd990', 1, 'adjective', null, 'aesthetic', 'Huset har et æstetisk udtryk.', 'The house has an aesthetic look.'), ('forære', 'word', '5f1b4551-7e58-5d6f-8b80-12cf9c3f55d5', 1, 'verb', null, 'to give (as a gift)', 'Han forærede hende en bog til fødselsdagen.', 'He gave her a book for her birthday.'), ('red', 'word', '784b7dc3-333a-5ec7-a1e8-c50bff2192bf', 1, 'noun', 'en', 'ford, shallows', 'De vadede over floden ved en red.', 'They waded across the river at a ford.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
